def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_score = 0
    opp_score = 0

    for my, opp in history:
        if my == 'C' and opp == 'C':
            my_score += 3
            opp_score += 3
        elif my == 'C' and opp == 'D':
            my_score += 0
            opp_score += 5
        elif my == 'D' and opp == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    # Count opponent defections and recent behavior
    opp_defections = sum(1 for my, opp in history if opp == 'D')
    my_defections = sum(1 for my, opp in history if my == 'D')

    # Recent window
    window = history[-10:] if n >= 10 else history
    recent_opp_def = sum(1 for my, opp in window if opp == 'D')

    # If opponent has defected a lot, retaliate
    if opp_defections > 0:
        ratio = opp_defections / n
        if ratio > 0.5:
            # heavily exploited, defect most of the time
            if rng.random() < 0.8:
                return 'D'
        elif ratio > 0.25:
            if recent_opp_def >= 3:
                return 'D'
            if rng.random() < 0.4:
                return 'D'

    # If we are behind, try to catch up by defecting occasionally
    if my_score < opp_score - 5 and n > 10:
        if rng.random() < 0.3:
            return 'D'

    # If we are ahead significantly, play nice
    if my_score > opp_score + 10:
        return 'C'

    # Near end of match, exploit if ahead or try to gain
    remaining = 100 - n
    if remaining <= 3:
        if my_score >= opp_score:
            return 'D'
        else:
            return 'C'

    # Tit-for-tat with forgiveness: if opponent just defected, defect once, else cooperate
    last_opp = history[-1][1]
    if last_opp == 'D':
        # Check if it was isolated
        if len(history) >= 3:
            prev2_opp = history[-2][1]
            prev3_opp = history[-3][1]
            if prev2_opp == 'C' and prev3_opp == 'C':
                # isolated defection, forgive with some probability
                if rng.random() < 0.5:
                    return 'C'
        return 'D'

    # Mostly cooperate
    if rng.random() < 0.1:
        return 'D'
    return 'C'

